function selectPiece(i){selected=i;legalTargets=legalMoves(i);render()}
function snapshot(){history.push({board:cloneBoard(board),turn,enPassant:enPassant?{...enPassant}:null,lastMove:lastMove?{...lastMove}:null,moveRows:moveRows.map(r=>({...r})),gameOver})}
function playMove(m){const moving=board[m.from],captured=m.enPassant?board[xy(m.to)[1]*8+xy(m.to)[0]]:board[m.to],fromName=coord(m.from),toName=coord(m.to);snapshot();applyRaw(m);const moved=board[m.to];let label=m.castle?(m.castle==='king'?'O-O':'O-O-O'):`${pieceName(moving)==='Pawn'?(captured?fromName[0]+'x':''):pieceGlyph[moving.type]||moving.symbol}${captured?'x':''}${toName}`;if(moved.promoted)label+='=Q';lastMove={from:m.from,to:m.to};const mover=turn;turn=opposite(turn);selected=null;legalTargets=[];const check=isInCheck(turn),hasMoves=allLegalMoves(turn).length>0;if(check)label+=hasMoves?'+':'#';moveRows.push({white:mover==='white'?label:'',black:mover==='black'?label:''});if(!hasMoves){gameOver=true;setStatus(check?`${colorName(mover)} wins by checkmate`:'Draw by stalemate')}else if(check)setStatus(`${colorName(turn)} is in check`);else setStatus(`${colorName(mover)} played ${pieceName(moving)} · ${colorName(turn)} to move`);render();renderLog()}
function allLegalMoves(color){const out=[];for(let i=0;i<64;i++)if(board[i]?.color===color)out.push(...legalMoves(i));return out}
function coord(i){const[x,y]=xy(i);return files[x]+(8-y)}
function setStatus(text){const el=document.querySelector('#moveStatus span:last-child');if(el)el.textContent=text}
function updateTurn(){const status=document.getElementById('turnText'),indicator=document.getElementById('turnIndicator'),white=document.getElementById('whitePlayer'),black=document.getElementById('blackPlayer');if(!status)return;status.textContent=gameOver?'Game over':`${colorName(turn)} to move`;indicator.style.background=turn==='white'?'#86a45b':'#354a39';white.querySelector('small').textContent=turn==='white'?'You’re up':'Waiting';black.querySelector('small').textContent=turn==='black'?'You’re up':'Waiting';white.classList.toggle('active-player',turn==='white'&&!gameOver);black.classList.toggle('active-player',turn==='black'&&!gameOver)}
function renderLog(){const log=document.getElementById('moveLog');document.getElementById('moveCount').textContent=`${moveRows.length*2-(moveRows.length&&moveRows.at(-1).black?0:moveRows.length?1:0)} PLIES`;if(!moveRows.length){log.innerHTML='<div class="log-empty"><span>♟</span> Your first move starts the story.</div>';return}log.innerHTML=moveRows.map((r,i)=>`<div class="move-row"><span class="move-number">${i+1}.</span><span class="move-entry ${i===moveRows.length-1&&r.white?'current':''}">${escapeHTML(r.white)}</span><span class="move-entry ${i===moveRows.length-1&&r.black?'current':''}">${escapeHTML(r.black)}</span></div>`).join('');log.scrollTop=log.scrollHeight}
function escapeHTML(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function undoMove(){if(placing){cancelPlacement();return}const s=history.pop();if(!s){toast('Nothing to undo yet.');return}board=cloneBoard(s.board);turn=s.turn;enPassant=s.enPassant;lastMove=s.lastMove;moveRows=s.moveRows;gameOver=s.gameOver;selected=null;legalTargets=[];setStatus('Move undone · your turn');render();renderLog()}
function resetGame(){board=initialBoard();turn='white';selected=null;legalTargets=[];history=[];moveRows=[];lastMove=null;enPassant=null;gameOver=false;setStatus('Standard setup · Make your move');render();renderLog();toast('Fresh board. Your move, White.')}
function buildPattern(){const grid=document.getElementById('patternGrid');grid.innerHTML='';for(let r=0;r<5;r++)for(let c=0;c<5;c++){const b=document.createElement('button');b.type='button';b.className='pattern-cell';b.dataset.dx=c-2;b.dataset.dy=2-r;if(r===2&&c===2){b.classList.add('center');b.textContent='✦';b.disabled=true}else b.onclick=()=>b.classList.toggle('marked');grid.appendChild(b)}}
let slideStyle=false;function setStyle(slide){slideStyle=slide;document.getElementById('stepToggle').classList.toggle('active',!slide);document.getElementById('slideToggle').classList.toggle('active',slide)}
function openModal(){document.getElementById('createModal').classList.add('open');document.getElementById('createModal').setAttribute('aria-hidden','false');document.getElementById('pieceName').focus()}
function closeModal(){document.getElementById('createModal').classList.remove('open');document.getElementById('createModal').setAttribute('aria-hidden','true');document.getElementById('modalError').textContent=''}
function createCustom(){const name=document.getElementById('pieceName').value.trim(),symbol=document.getElementById('pieceSymbol').value.trim()||'✦',color=document.getElementById('pieceColor').value,moves=[...document.querySelectorAll('.pattern-cell.marked')].map(b=>({dx:+b.dataset.dx,dy:+b.dataset.dy}));if(!name){document.getElementById('modalError').textContent='Give your piece a name first.';document.getElementById('pieceName').focus();return}if(!moves.length){document.getElementById('modalError').textContent='Choose at least one direction for your piece.';return}const def={id:Date.now().toString(36)+Math.random().toString(36).slice(2,5),name,symbol,color,slide:slideStyle,moves};customDefs.push(def);saveCustoms();renderCustomList();document.getElementById('pieceName').value='';document.getElementById('pieceSymbol').value='✦';document.getElementById('symbolPreview').textContent='✦';document.querySelectorAll('.pattern-cell.marked').forEach(b=>b.classList.remove('marked'));setStyle(false);closeModal();activatePlacement(def.id);toast(`${name} is ready to place.`)}
function loadCustoms(){try{const data=JSON.parse(localStorage.getItem('oddboard-custom-pieces')||'[]');if(Array.isArray(data))customDefs=data.filter(d=>d&&d.id&&d.name&&Array.isArray(d.moves))}catch{customDefs=[]}}
function saveCustoms(){try{localStorage.setItem('oddboard-custom-pieces',JSON.stringify(customDefs))}catch{}}
function renderCustomList(){const list=document.getElementById('customList');document.getElementById('pieceCount').textContent=customDefs.length;if(!customDefs.length){list.innerHTML='<div class="empty-piece"><span class="empty-glyph">✳</span><span>Your inventions will live here.</span></div>';return}list.innerHTML=customDefs.map(d=>`<div class="custom-piece-card"><span class="piece-token">${escapeHTML(d.symbol)}</span><span class="custom-info"><b>${escapeHTML(d.name)}</b><small>${colorName(d.color)} · ${d.slide?'Sliding':'Stepping'}</small></span><button class="place-piece ${placing===d.id?'active':''}" data-place="${d.id}" title="Place ${escapeHTML(d.name)}">↗</button><button class="delete-piece" data-delete="${d.id}" title="Delete piece">×</button></div>`).join('');list.querySelectorAll('[data-place]').forEach(b=>b.onclick=()=>activatePlacement(b.dataset.place));list.querySelectorAll('[data-delete]').forEach(b=>b.onclick=()=>deleteCustom(b.dataset.delete))}
function activatePlacement(id){placing=placing===id?null:id;selected=null;legalTargets=[];renderCustomList();document.getElementById('placementHint').innerHTML=placing?'<span class="hint-mark">↗</span> Tap any square to place your piece.':'<span class="hint-mark">↗</span> Choose a piece above, then tap a square to place it.';render()}
function placeCustom(i){const def=customDefs.find(d=>d.id===placing);if(!def)return;snapshot();board[i]=makePiece('custom',def.color,{name:def.name,symbol:def.symbol,slide:def.slide,moves:def.moves.map(m=>({...m})),customId:def.id});placing=null;setStatus(`${def.name} placed on ${coord(i)} · ${colorName(turn)} to move`);renderCustomList();render()}
function cancelPlacement(){if(!placing)return;placing=null;renderCustomList();document.getElementById('placementHint').innerHTML='<span class="hint-mark">↗</span> Choose a piece above, then tap a square to place it.';render()}
function deleteCustom(id){const def=customDefs.find(d=>d.id===id);if(!def)return;customDefs=customDefs.filter(d=>d.id!==id);saveCustoms();renderCustomList();if(placing===id)cancelPlacement();toast(`${def.name} removed from the workshop.`)}
function toast(text){const el=document.getElementById('toast');el.textContent=text;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2300)}
function showHelp(){const backdrop=document.getElementById('createModal'),modal=backdrop.querySelector('.modal'),old=modal.innerHTML;modal.innerHTML='<button class="modal-close" aria-label="Close">×</button><div class="eyebrow">A QUICK FIELD GUIDE</div><h2>How to play.</h2><div class="help-content"><p><b>Move:</b> Tap one of your pieces, then tap a highlighted square. Legal chess moves are enforced, including check, castling, en passant, and promotion.</p><p><b>Invent:</b> Create a custom piece, pick its movement directions and whether it steps one square or slides as far as it can. Choose a side, then place it anywhere on the board.</p><p><b>Experiment:</b> Placement is free-form sandbox editing and doesn’t change whose turn it is. Use Undo to rewind the last move or placement; Reset restores the standard starting position.</p><p><b>Note:</b> Custom pieces follow their chosen movement rules and can give check or checkmate.</p></div><div class="modal-actions"><button class="save-piece-btn" id="closeHelp">Got it</button></div>';backdrop.classList.add('open');modal.querySelector('.modal-close').onclick=()=>{modal.innerHTML=old;backdrop.classList.remove('open');bindHelp()};modal.querySelector('#closeHelp').onclick=()=>{modal.innerHTML=old;backdrop.classList.remove('open');bindHelp()};backdrop.onclick=e=>{if(e.target===backdrop){modal.innerHTML=old;backdrop.classList.remove('open');bindHelp()}}}
function bindHelp(){document.getElementById('helpBtn').onclick=showHelp}
init();

